<?php
namespace App\Services\Finance;
use App\Models\Invoice; use App\Models\PreinvoiceOrder; use Carbon\CarbonImmutable; use Illuminate\Database\Eloquent\Builder; use Illuminate\Support\Facades\DB;
class SellerCommissionSalesPreviewService {
 public function __construct(private readonly SellerCommissionBasePreviewCalculator $calculator) {}
 public function report(array $f): array { $q=$this->query($f); $s=['invoice_count'=>(int)(clone $q)->count(),'total_sales'=>(int)(clone $q)->sum('invoices.total'),'cash_collected'=>(int)(clone $q)->sum('cash_collected'),'calculated_commission_total'=>0,'missing_rate_invoice_count'=>0,'missing_rate_item_count'=>0,'missing_rate_base_total'=>0]; $this->calculator->warm($f['date_from'],$f['date_to']); (clone $q)->with(['items.product.category','items.variant'])->orderBy('invoices.id')->chunkById(100,function($invoices)use(&$s){foreach($invoices as $invoice){$preview=$this->calculator->calculate($invoice);$s['calculated_commission_total']+=$preview['calculated_commission_total'];$s['missing_rate_item_count']+=$preview['missing_rate_item_count'];$s['missing_rate_base_total']+=$preview['missing_rate_base_total'];if($preview['missing_rate_item_count']||$preview['warnings'])$s['missing_rate_invoice_count']++;}},'invoices.id','id'); $p=$q->with(['items.product.category','items.variant'])->orderByDesc(DB::raw('COALESCE(invoices.document_date, invoices.created_at)'))->orderByDesc('invoices.id')->paginate(25)->withQueryString(); foreach($p as $invoice)$invoice->base_preview=$this->calculator->calculate($invoice); return ['summary'=>$s+['cash_ratio'=>$s['total_sales']>0?$s['cash_collected']*100/$s['total_sales']:0],'invoices'=>$p]; }
 private function query(array $f): Builder { [$from,$to]=[CarbonImmutable::parse($f['date_from'],config('app.timezone'))->startOfDay(),CarbonImmutable::parse($f['date_to'],config('app.timezone'))->endOfDay()];$seller=Invoice::effectiveSellerSql('invoices','preview_preinvoices');$cash=DB::table('invoice_payments')->selectRaw('invoice_id, SUM(amount) as cash_collected')->where('method','cash')->groupBy('invoice_id');return Invoice::query()->select('invoices.*')->selectRaw("{$seller} as effective_seller_id")->selectRaw('COALESCE(preview_cash.cash_collected, 0) as cash_collected')->join('preinvoice_orders as preview_preinvoices','preview_preinvoices.id','=','invoices.preinvoice_order_id')->leftJoinSub($cash,'preview_cash','preview_cash.invoice_id','=','invoices.id')->where('preview_preinvoices.status',PreinvoiceOrder::STATUS_CONVERTED_TO_INVOICE)->whereRaw("{$seller} = ?",[(int)$f['seller_id']])->whereBetween(DB::raw('COALESCE(invoices.document_date, invoices.created_at)'),[$from,$to])->when(filled($f['invoice_number']??null),fn(Builder $q)=>$q->where('invoices.uuid','like','%'.trim($f['invoice_number']).'%'))->when(filled($f['customer']??null),function(Builder $q)use($f){$t='%'.trim($f['customer']).'%';$q->where(fn(Builder $i)=>$i->where('invoices.customer_name','like',$t)->orWhere('invoices.customer_mobile','like',$t));}); }
}
